class ResourceGuard {
    Resource* r; // Hypothetical C-style resource

public:
    explicit ResourceGuard(Resource* res) : r(res) {} // Acquire

    // Destructor guarantees release, even on exceptions
    ~ResourceGuard() { 
        if (r) r->release_resource();
    }
    // No copy/move operations allowed (Rule of 5 implied)
};

// --- Standard Library RAII (Memory) ---
struct Data {};

void safe_function() {
    // Resource acquisition initializes object 'd'
    std::unique_ptr<Data> d = std::make_unique<Data>(); 

    // ... code that might throw ...

    // d->~unique_ptr() called automatically on scope exit
}

// --- Standard Library RAII (Synchronization) ---
std::mutex mtx;

void thread_safe_op() {
    // Lock acquired in ctor
    std::lock_guard<std::mutex> lock(mtx); 

    // Critical Section: Exception safe

    // Lock released in dtor (guaranteed)
}
